    for (int i = 0; i < n; i++)
        adjList[i] = NULL;

    printf("Enter edges (u v):\n");
    for (int i = 0; i < e; i++) {
        scanf("%d %d", &u, &v);

        // add edge u -> v
        struct Node* newNode = createNode(v);
        newNode->next = adjList[u];
        adjList[u] = newNode;

        // add edge v -> u (undirected)
        newNode = createNode(u);
        newNode->next = adjList[v];
        adjList[v] = newNode;
    }
    printf("Graph created!\n");
}

// --- Display Graph ---
